(window.webpackJsonp=window.webpackJsonp||[]).push([[110],{545:function(t,s,v){"use strict";v.r(s);var _=v(11),e=Object(_.a)({},(function(){var t=this,s=t.$createElement,v=t._self._c||s;return v("ContentSlotsDistributor",{attrs:{"slot-key":t.$parent.slotKey}},[v("p",[v("font",{attrs:{size:"5"}},[t._v("摘要：对于那些把我们引向基督的人，我们要接受他们的影响，走向基督；但一旦来到主面前，在心态上我们就要和他们“告别”。而在主面前，我们则要完全地倚靠他，竭力让他的生命充满我们的心，在每一件事、每一个人面前，不辜负神托付给我们的使命。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("大家平安。我们今天继续来分享路加福音7:24~35节的内容。我们一起来读。今天我们这篇讲道的题目是：做一个容易受影响的人。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("初看这个题目，大家可能会觉得这与我们现在所受到的很多教导不太一样，包括教会圈子中的教导。我们被教导要意志坚定、有主见。尤其是在信仰问题上，要坚定、对神忠贞不二；不要作小孩子，被异教之风摇动，飘来飘去。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("这些都是对的。在有些问题上，我们确实要意志坚定，抵御外部信息的错误影响。但如果走向极端，在该受影响的地方，却自我封闭、固执己见，那就会给我们造成巨大的损害。我相信大家从上一次讲道中，已经可以明白这个道理了。根据实际的经验去调整自己主观上对神的认识，其实就是一个不断受外界影响的过程。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("今天，我们就一起借着7:24-35节的经文，更深入地想一想：在我们每天的信仰生活里，到底该怎么具体地去面对、去处理那些从外界来的影响。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("一、被人影响，走向基督")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("上次我们讲到，约翰曾差派门徒来问耶稣到底是谁。今天这段经文，就紧接在那件事之后——是主耶稣当着众人的面，公开评价约翰。要准确理解主耶稣的这番话，我们需要先回到当时的历史背景里。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("要知道，施洗约翰在当时的犹太社会，是位影响力极大的人物。马太福音3:5节记载，当约翰出来传道的时候，“耶路撒冷和犹太全地的人，都出去到他那里，承认他们的罪，在约旦河里受他的洗。”这节经文描述的是他在南部，也就是犹太地区的影响力。而今天我们读到的这段经文，事情发生在北部的加利利地区。即便在这里，从7:29节我们仍然可以看出，约翰的影响力依然广泛——这里有许多百姓，也曾经受过约翰的洗。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("接下来我们一起翻到约翰福音1:19-37节。1:19-34节讲到，施洗约翰公开作见证，指出那位拿撒勒人耶稣就是基督。接着第35-37节特别提到，有两个人因为听见约翰的见证，就转而跟从了耶稣——一个是西门彼得的兄弟安得烈，另一个没有记下名字，但教会传统一般认为，他就是这本福音书的作者、使徒约翰。后来，这两个人都被主拣选，成了十二使徒中的两位。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("从这段记载我们可以清楚地看到：施洗约翰这位大有影响力的人，曾经怎样热情、积极地将人引向耶稣。因为他清楚地知道，这位拿撒勒人耶稣就是基督，是众先知所预言的弥赛亚，而他自己的使命，就是为他预备道路。安得烈和使徒约翰，正是许许多多因约翰的影响而来到耶稣面前之人的代表。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("但我们从上次的经文，就是路加福音7：18~23节看到，这位有着巨大影响力、曾经向人们做出见证的拉比，却对主耶稣的身份产生了疑惑。于是他差派门徒来进行询问，而主耶稣也给予了回应。关键问题是，这件事不是在私下发生的。从路加福音7:21节可以看到，约翰的门徒来询问时，耶稣正在公开医治病人，周围有很多人看着、听着。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("这样一来，在场的人心里就会产生一连串的疑问：我们该怎样看待施洗约翰？他现在的质疑意味着什么？他的质疑是错的吗，但他不是先知吗？如果他质疑得对，那他以前对这位拿撒勒人耶稣的见证，难道是错的吗？这样一来，他从前所作的见证，我们今天还要不要信？这位拿撒勒人耶稣，到底是谁？")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("你看，施洗约翰这一次的询问，就像一颗石子投入水中，涟漪一圈圈扩散出去，在许多人心里激起各样的困惑与不安，甚至可能最终让一些人对耶稣的身份，也产生同样的怀疑。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("类似这样的经验，我想大家或多或少都经历过。一个人能对你有影响力，意味着你相信他——至少在某些事上、在某种程度上。你是基于对他的信任，才去接受了某件事。可如果他本人后来在这件事上表现得不一样了，你的心就可能被动摇。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("最典型的例子，可能就是在自己家人面前为主作的见证。上次在分享中，这位姐妹提到，她受洗前，她爱人曾劝她别受洗了，理由是：你看女儿信了耶稣，脾气不还是那么大吗？这句话给我印象很深。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("其实我自己也有过类似的经历。信主之后，我很热心地向家人传福音。我对他们——尤其对我妈妈——是有一定影响力的。她因为相信我，愿意信主，也做了决志祷告。可是，当我自己的生活表现，跟我所信的、所传的并不一致的时候，她也就对主耶稣产生了动摇。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("这正是我们刚才讲的那种心理模式：一个人因为受另一个人的影响而接受一件事，可当这个“有影响力的人”自己与这件事出现不一致时，就可能导致受影响的人对这件事本身产生疑惑。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("通过我以上的介绍，希望大家能感受到，施洗约翰对耶稣的这番疑问，会给当时在场的人带来怎样的心理波动。我们今天的基督徒，可能不太能体会约翰在当年犹太社会中的威望，所以也容易忽略他的一举一动对众人产生的影响。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("而在今天的经文里，主耶稣正是要面对、也要处理施洗约翰这次询问在人们心中激起的涟漪。他不但没有回避，反而抓住这个机会，进一步教导他们、引导他们的心。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("带着这样的认识，我们一起进入到经文当中。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("在第24到26节，主耶稣肯定了众人对施洗约翰的“相信”是正确的。他先用三个问句，点明大家当初去旷野找约翰时心里想看的是什么：你们出去，是要看风吹动的芦苇吗？是要看穿细软衣服的人吗？不，你们是要看一位“先知”。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("在这三个问句中，“风吹动的芦苇”、“穿细软衣服的人”与“先知”构成了对比。从这对比中，就反衬出众人对约翰这位先知的认识是什么样的。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("芦苇随风倒，代表没有立场、软弱摇摆的人。但施洗约翰不是这样的，他意志坚定、恪守神的律法、坚守神的使命。马太福音3:7~10记载，对于那些要来受洗的宗教领袖，他不但没有去曲意逢迎，反而严厉斥责他们是“毒蛇的种类”，警告他们不要以为自己的犹太血统能为他们赢得救恩。路加福音第3章记载，当群众来问他们当做什么，他没有轻飘飘地说：“你们悔改，有信心就好了，因信就称义了”，而是要求他们必须要有具体的行动，与他们悔改的心相称。对于当时的分封王希律所犯的罪，他也是坚决地予以责备，即使被下监也毫不妥协。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("“穿细软衣服的人”，主耶稣在7：25节解释，是指那些在皇宫里宴乐度日的人。他们只看得见今生，追求口腹的满足、世上的享受，眼里没有永恒。约翰不是这样，他并不贪图今生的富足安逸，而是在苦修中执行神的使命、等待天国的来临。马太福音3:1~4节描述他住在旷野，在那里传道，穿骆驼毛的衣服、腰素皮袋，吃的是蝗虫野蜜。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("所以，主耶稣在路加福音7:24~26节这段话中首先向群众们确认：“你们认为约翰是一位先知，这是正确的”。不仅如此，他在第26节还进一步确认，“他比先知大多了”。这句话是什么意思呢？在第27节他自己做了解释：“经上记着说：‘我要差遣我的使者在你前面预备道路’，所说的就是这个人。”")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("也就是说，主耶稣肯定约翰是先知，但他又不是一般的先知，而是比其他的先知“大多了”。从第27节我们就可以明白，这个“大”，不是体现在他的能力上，不是体现在他的地位上，也不是体现在他对人们的影响力上，而体现在他的任务、使命上。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("我们知道，犹太民族历史上有很多伟大的先知，摩西、大卫、撒母耳、以赛亚等等。要论能力、地位、影响力，很显然不能说施洗约翰比他们“大得多”。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("那如何从他的使命的角度来理解他是一位“大得多”的先知呢？")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("这需要我们明白神整个救赎计划。从亚当、夏娃犯罪之后，神的救恩工作就开始了。他先拣选了一个家族——从亚当、塞特、挪亚，到亚伯拉罕、以撒、雅各——又让这家族成为一个民族，就是旧约的以色列。在这个长达近四千年的历史中，他通过这个家族、民族来逐渐启示他自己。可以说这是他救赎的预备阶段。预备期结束，神就差遣他的独生子亲自来到世上，实际执行救赎，把他所拣选的人从罪中拯救出来，与神和好。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("在约翰以前的众先知，他们的使命和这“实际的救赎执行”还没有发生直接关系。他们是神在预备阶段所兴起的，向他所拣选的家族、民族传达启示，其中最多也就是预言将来要来的那一位救主。唯独施洗约翰，他的使命是直接为这救赎的“实际执行”预备道路——为主铺路，预备人心。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("所以约翰比其他先知更大，是指他的使命与“神的救恩实现”之间，有更直接的关系。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("我再明确一下，这个“更大”是指使命的 “直接性”，而不是指“重要性”。要说重要性，每一位先知的工作都不可或缺，都在神的计划中有其必要，没有谁比谁次要。但如果要说与救赎实际执行之间的“直接关联”，约翰的使命是更直接的。大家能理解吧？")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("正是从这个意义上，主在第28节接着说：“我告诉你们：凡妇人所生的，没有一个大过约翰的。”这还是在强调约翰的使命与神救赎的实现之间那种特别的、直接的关系。他是那位为主铺路的人，而主的到来，就标志着神对人类的救赎正式进入了实际执行的阶段。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("所以，主耶稣在7:24-28节这段讲话里要显明的意思就很清楚了。他告诉众人：“你们对约翰的认识是对的，他的确是先知，而且他就是那位为我的到来预备道路的。所以，他对我的见证是可信的。你们因受他的影响而来到我这里，这条路走对了。”")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("但大家注意，主耶稣是在什么背景下来说这段话的？我刚才已经解释了，是在约翰公开地对他产生了疑惑的时候，而当时有许多人，正是因为受了约翰的影响才来跟从主的。所以，约翰的疑惑很可能变成他们的疑惑。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("在这个背景下，主耶稣特意强调约翰的使命，其实更是在提醒众人：“你们不要忘了他的使命是什么。他的使命是预备好你们的心、把你们引导我这里来。所以，当你们受他的影响，按照他的指引来到我这里之后，对你们而言，他的使命就结束了。当你们来到我这里，你们的心就不能再滞留在他那里，继续被他那些与这使命不符的念头或举动所左右。如果是这样，你们就和他形成了一种依附，你们实际上就没有按照神的旨意，到我这里来。”")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("弟兄姐妹们，这是一个非常重要的认识。我们心里一定要清楚：在我们信仰的路上，神会安排各种各样的人来到我们身边，把我们带向他的儿子耶稣基督。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("对你来说，这个人可能是一位朋友、一位亲人，甚至是一位多年前偶然遇见的路人，是他把福音第一次传给了你；也可能是你的父母，从小就把主耶稣介绍给你。这个人，可能是你过去、现在、将来在教会或团契中遇到的某位牧者、某位弟兄姐妹，他们被主感动，来劝勉你、扶持你。而在今天、在这里，这个人就是我，神安排我站在这里，把这篇道讲给你们听。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("所以一方面，我们要愿意成为一个容易被影响的人，心里不要刚硬。这样，我们才能借着神所安排在我们身边的人来被影响，我们就可以开始认识主，或者一天比一天更认识他。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("但另一方面，我们也要清楚：这些影响我们的人，当他们把我们引到基督面前，或者帮助我们更深地进入主里面的时候，对我们个人而言，他们的使命其实就已经完成了。我们的心不能再停留在他们身上，继续被他们可能有的、与这使命不符的念头或行为所牵引。我们可以、也应该受人的影响走向基督，但绝不能在心理上对这个人形成一种依附。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("拿我自己举例。今天我站在这里讲这篇道，待会儿也会和大家有些交流。我今天的使命，就是藉着这些信息，带领大家更深入地进入基督。所以你们不要对我的话毫无反应，你们应当被影响，被触动。当你们因着这样的影响，更多认识基督、更深地与他建立关系，那么对你来说，我今天的使命就结束了。如果明天你听说我去信佛了，或者我在家虐待孩子，甚至我突然打电话把你羞辱一顿——这些都不该影响你与主之间，已经因今天的信息而变得更紧密的关系。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("如果不认识到这一点，在心态上对人形成依赖，这是非常危险的。因为人都是有限的，都是有软弱的。就连意志那样坚定、一生恪守神的律法、在苦修中坚守使命、殷切等候天国的施洗约翰，都会有疑惑摇动的时候，更何况其他人呢？")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("初信的人特别容易掉进这种危险的属灵境地里。就像我刚才举的例子，有些亲人是因着彼此的信任而信主的，可一旦发现给他们传福音的亲人生命表现和所信的福音不太一样，他们自己反而因此离开了福音。为什么呢？因为初信者与主的关系还比较脆弱，所以会有意无意地在心理上依赖这些自己信得过的人。一旦这些人的生命表现和所传讲的不一致，那些依赖他们的人就跟着跌倒了。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("不仅初信者，很多老信徒也是这样。他们把自己的心依附于某个牧师、某个传道人，结果这个牧师、传道人出了问题，于是他们的属灵生命也大受摧残。我们不时就会听说的那些受属灵虐待之苦的受害者，不就是这样吗？")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("最近网上有两则消息，一是四川某教会的传道人，长期性侵教会的姐妹；二是北京某教会的传道人，带领会众集体迁往印尼，然后打着投资高利润咖啡店的幌子，对会众搞庞氏骗局。这些受害者的遭遇确实令人痛心，他们对主的信心、与主的关系，无疑都将因此受到重创，有些人甚至需要相当长的时间，才能慢慢从属灵的伤痕中恢复过来。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("还有一种不同的表现。我认识一位姐妹，她很追求主，但多年来一直拒绝受洗。她的理由听起来很“谨慎”：人都是有问题的，所以凡是和人有关的事，她都持怀疑态度。受洗需要人施洗，她无法确认这人是否可靠，所以要怀疑；受洗是奉圣父、圣子、圣灵的名，而“三位一体”是人归纳出来的教义，她同样要怀疑。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("表面上看，她似乎很“独立”，好像只愿单单活在神面前。但这其实是一种应激性的反应——过去她在潜意识里曾依附于人，结果受伤了，就发展出对一切“与人相关之事”的过度防备。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("这位姐妹刚接触信仰时，进过一个否认三位一体的异端团体；后来被神带领离开，在一个正统教会聚会，结果那个教会的牧师又陷入淫乱，并卷款潜逃。这些经历让她对一切涉及人的事都充满怀疑，最后甚至走向一个极端：为了不碰脏水，把澡盆里的孩子连同洗澡水一起倒掉了。结果，连神在圣经中设立、并命定要藉着不完美的人来施行的洗礼，她也一并拒绝。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("这些例子虽然都比较极端，但从中我们应当警醒、反思：怎样才能不落入同样的境地？答案就在于我们要清醒地认识到——神确实会使用人，哪怕是不完美、有缺点的人，来作引导我们认识他的工具。所以我们不要心硬，要愿意被影响，这样才能像当年那些百姓因约翰的影响而来到主面前一样，走向主、遇见主。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("但同时，我们也要意识到，人对我们的影响，必须限定在“帮助我们认识主、亲近主”这个目标之内。一旦藉着他们的帮助达到了这个目的，对我们个人而言，他们的使命就已经完成了。他们其他的想法、言行，就不该再继续牵引我们。这也正是主耶稣在这段经文里对那些百姓的提醒。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("不要忘记，主耶稣才是我们最终要去向的那一位。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("二、被主影响，忠于使命")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("那么，当我们来到主面前之后，又该如何在他面前做一个容易受影响的人呢？我们再看第28节的经文。主在这里先强调了约翰使命的“直接性”，这一点刚才我们已经讨论过了。接着，他话锋一转，说：“然而，神国里最小的比他还大。”")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("这里出现了一个对比——一边是“妇人所生的人”，一边是“神国里的人”。在这段上下文中，约翰显然属于“妇人所生的人”，而不属于“神国里的人”。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("这是什么意思？这不是在说施洗约翰不得救、要下地狱。当然不是。在将来的新天新地里，我们一定会见到他，就像我们也会见到摩西、大卫、以赛亚、但以理等等众先知一样。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("那么，这段经文里所说的“神国里的人”究竟指的是谁呢？路加在这里没有明说，但显然，当时在场的人是听懂的。所以第29节才会记载，他们听见这话，就“以神为义”——正是因为心里明白了，才会有这样的反应。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("从第29节对“众百姓和税吏”的描述来看，他们正是那些受了约翰的影响而来跟从耶稣的人。我们不要以为跟从耶稣的只有那十二个使徒，当时还有许多人跟随他。其中有相当一部分，是直接因约翰的见证而来的，使徒安得烈和使徒约翰就是他们的代表，这个我之前已经提过。这些人，有些跟着耶稣一起游历，有些在他出现的地方寻找他、听他讲道。所以极有可能，当主耶稣在第6章讲“平地宝训”的时候，第7章29节这里所说的“众百姓和税吏”也在场。而平地宝训一开头就说：“你们贫穷的人有福了，因为神的国是你们的”，整篇讲论正是在描述“神国里的人”该有的样子。正因如此，当主在这里再次提到“神国里的人”，他们立刻就能明白指的是什么。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("关于“平地宝训”，之前我用四次讲道分享过，也请大家回头复习过。我们可以这样概括：神国里的人，就是那些承认自己一无所有、一无所能，因此在一切事上都完全倚靠主耶稣的人。除了主，他们没有任何别的倚靠；除了主，他们也不从别处得着满足。也正因如此，主的生命充满了他们的心。无论面对谁，他们都带着主的心去爱他、去做对他真正有益处的事。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("大家看，平地宝训所描述的神国之人，其实包含两个层面的状态：一是他们内心的状态——要摆脱一切缠累，完全降服于主的带领，完全满足于主的供应；二是他们对待别人的状态——要爱人，并做出对他人有益的行动。而对人最大的益处，莫过于帮助他进入神的国。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("所以，神国里的人就是做两件事：对内，是操练自己的心，越来越降服于主的带领，满足于主的供应；对外，是怀着爱人的心，采取实际行动，把对方带进神的国。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("请大家记住，这就是神国之人所领受的使命。我们可以把它总结为：扩展神的国度，或者说，扩展神救赎的果效。很显然，这个使命有两个层面：一个是在自己里面扩展——让神的国、神救赎的果效在自己心里不断成长，也就是心越来越顺服神、享受神。这就是我们常说的“成为圣洁”。另一个是在自己之外扩展——让神的国、神救赎的果效也临到别人，也就是让其他人也越来越顺服神的律法、享受神。这就是我们常说的传福音、带门徒、造就弟兄姐妹，用生命和话语向人见证神救赎的大能。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("因此，“神国里的人”，指的就是在神的救赎开始执行之后，被神拣选、来履行这使命的人——对内对外，扩展神的国，扩展神救赎的果效。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("在主耶稣到来之前，是神救赎的预备阶段，那时神的国还没有降临。在这个意义上，无论是约翰，还是摩西、大卫，都不是“神国里的人”，而是“妇人所生的人”。但当救主降世，就把神的国带进了世界，神的救赎就进入了执行和实现的阶段。此后所有被神拣选的人，都是在神国已经到来的情形中，去履行神所赋予的这个使命。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("大家跟上这个救赎展开的脉络了吗？约翰以前的先知，是预言神救赎的实现；约翰，是为神救赎的实现预备人心；主耶稣自己，是亲自实现了神的救赎；而之后神的选民，则是去扩展这已经实现的神救赎的果效。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("所以，就“神救赎的实现”来说，约翰的使命比之前的先知更直接；而之后神选民的使命，相比于约翰，又与神救赎的实现有着更为直接的关系。这就是为什么主耶稣在7：28节说：“神国里最小的比约翰还大。”我们必须从“神所托付的使命”与“神救赎的实现”之间的“直接程度”，来理解这个“小”和“大”。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("这就是主耶稣在澄清了施洗约翰的身份之后，对众人做的进一步教导：约翰把你们带到我这里，他的使命已经完成了；而你们，也有你们的使命——并且你们的使命，与神的救赎是更加直接相关的。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("路加记载，那些来到主耶稣面前的人，实实在在地被主的话所影响。第29节说，他们“听见这话，就以神为义”。所谓“以神为义”，最直白的理解，就是承认神是对的，他所说的、所做的都是对的、是公义的。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("当初，施洗约翰告诉他们：“你们要悔改，因为救主马上就要来了”，并且他指着拿撒勒人耶稣说：“这就是那位救主。”他们因着约翰的影响，受了他的洗，听了他的见证，最终来到了基督这里。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("现在，主耶稣亲自告诉他们：“跟随我的人，就是神国的人；神国之人的使命，就是去扩展神的国度，去扩展神救赎的果效，让神救赎的大能既彰显在自己的生命里，也传递给更多的人。”他们又被主的话深深影响。于是，他们接受、认同了主的话。当然，真正的接受和认同，必然带来实际的行动——对内，操练自己摆脱一切的缠累，完全降服于主的带领，完全满足于主的供应；对外，则以爱心去对待人，做真正对他人有益处的事。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("弟兄姐妹们，这就是我们应当在主面前做一个“容易受影响的人”该有的样子。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("我们既然跟随主，就是神国里的人；神也把这同样的使命托付给了我们——去扩展他的国度，扩展他救赎的果效。所以我们要意识到：我们每天遇到的事，不是生活中的鸡毛蒜皮；我们每天见到的人，也不是时空里的甲乙丙丁。这些都是神特意安排在我们周围、让我们去执行他使命的具体场景。你怎么回应每一件事、怎样对待每一个人，都关系到你是在推动，还是在抵挡神国度和救赎果效的扩展；都关系到你是在忠心地履行神给你的托付，还是像一个又恶又懒的仆人，在那里消极怠工。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("所以我们千万不要把一场家庭冲突看成小事，不要把上一堂课看作平常，不要把做一顿饭当作无关紧要，也不要轻易放过一次和同学、同事的纷争。我们要被主耶稣的话所影响，因此去反省：我该怎样在这件事上、在这个人面前，扩展神的国度、彰显神救赎的果效？我的心应当如何？我对这个人应该是怎样的？而我实际上是怎样的？我为什么会这样？我该汲取什么教训？我该求神怎样改变我，好让我下一次面对类似的事、类似的人时，能推动而不是抵挡神国度和救赎果效的扩张？")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("大家看见了吗？当你持续这样反省，并且因此更忠实地活出神的使命，这才说明你的心不是刚硬的，你在主面前是一个容易受影响的人。这才说明你真的“听见了主的话，就以神为义”。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("弟兄姐妹们，这就是我今天从这段经文里想和大家分享的信息：怎样按照圣经的启示，做一个“容易受影响的人”。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("对于那些把我们引向基督的人，我们要接受他们的影响，走向基督；但一旦来到主面前，在心态上我们就要和他们“告别”，不再依附于他们，免得他们的软弱反过来破坏我们与主的关系。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("而在主面前，我们则要完全地倚靠他，竭力让他的生命充满我们的心，在每一件事、每一个人面前，都认同他的话、活出他的话，忠心地扩展神的国度，不辜负神托付给我们的使命。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("路加福音7:35节说，这样去做一个容易受影响的人，就是“智慧之子”。他们在人面前虚心却不依附，在主面前谦卑却不懒散——这正是按着神的智慧，去面对人、面对主时该有的样子。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("与之相对的，就是愚蠢。感谢主，他不仅教导我们如何做智慧人，也通过路加在7:30~34节，记载了一些蠢货们作为我们的警戒。这些人“意志坚定”、“态度坚决”。他们拒绝受约翰的影响，因此不能认识拿撒勒人耶稣是谁；他们当然更是拒绝受耶稣的影响，反而指责他是贪食好酒。路加在第30节遗憾地说，如此他们就废弃了神对他们旨意。神愿意每个人都能来到主耶稣面前，得到他所完成的救恩，因此派遣约翰前来，使犹太人能被他影响，走向基督。当法利赛人和律法师们拒绝受影响，也就与基督、与救恩无缘了。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("弟兄姐妹们，你是这样的“蠢人”吗？或者，你有没有过类似愚蠢的时候——拒绝被人影响，拒绝听牧师的教导、不听弟兄姐妹的劝勉，以致于你无法更深地走进与主的关系里？")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("又或者，你是另一种愚蠢：你容易受人影响，却停在那里，依附于人，不走向基督，结果你与基督的关系，总是因别人的软弱而受损害？")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("再或者，你又是另一种愚蠢：你虽然来到基督面前，却不受他的影响，每天只顾吃喝拉撒、家长里短，浑浑噩噩，辜负了神托付你的使命。所以你的生命长期没有改变，在与人的相处中、在面对艰难时，仁爱、喜乐、和平、忍耐、恩慈、良善、信实、温柔、节制——这些生命的美丽果子，你结不出来；对你周围的人，你没办法去爱他们、去做对他们真正有益的事，尤其是当他们伤害你的时候。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("愿我们每个人，都在智慧上天天长进，而不是在愚蠢里越陷越深。")])],1)])}),[],!1,null,null,null);s.default=e.exports}}]);